import pandas as pd

def merge_events(events):
    # events: list of [hall_id, start, end]; returns merged list
    changed = True
    evs = [list(e) for e in events]
    while changed:
        changed = False
        out = []
        used = [False] * len(evs)
        for i in range(len(evs)):
            if used[i]:
                continue
            s, e = evs[i][1], evs[i][2]
            for j in range(i + 1, len(evs)):
                if not used[j] and evs[j][0] == evs[i][0] and s <= evs[j][2] and evs[j][1] <= e:
                    s = min(s, evs[j][1]); e = max(e, evs[j][2]); used[j] = True; changed = True
            out.append([evs[i][0], s, e])
            used[i] = True
        evs = out
    return evs

