import java.util.*;

class Solution {
    public List<int[]> mergeEvents(int[][] events) { // {hall, start, end}
        boolean changed = true;
        List<int[]> evs = new ArrayList<>();
        for (int[] e : events) evs.add(e.clone());
        while (changed) {
            changed = false;
            List<int[]> out = new ArrayList<>();
            boolean[] used = new boolean[evs.size()];
            for (int i = 0; i < evs.size(); i++) {
                if (used[i]) continue;
                int s = evs.get(i)[1], e = evs.get(i)[2];
                for (int j = i + 1; j < evs.size(); j++) {
                    int[] b = evs.get(j);
                    if (!used[j] && b[0] == evs.get(i)[0] && s <= b[2] && b[1] <= e) {
                        s = Math.min(s, b[1]); e = Math.max(e, b[2]);
                        used[j] = true; changed = true;
                    }
                }
                out.add(new int[]{evs.get(i)[0], s, e});
                used[i] = true;
            }
            evs = out;
        }
        return evs;
    }
}

