def merge_events(events):
    # events: list of [hall_id, start, end]
    evs = sorted(events, key=lambda e: (e[0], e[1]))
    res = []
    cur_hall, cur_start, cur_end = None, None, None
    for h, s, e in evs:
        if h != cur_hall or s > cur_end:
            if cur_hall is not None:
                res.append([cur_hall, cur_start, cur_end])
            cur_hall, cur_start, cur_end = h, s, e
        else:
            cur_end = max(cur_end, e)
    if cur_hall is not None:
        res.append([cur_hall, cur_start, cur_end])
    return res

