vector<vector<int>> mergeEvents(vector<vector<int>>& events) { // {hall, start, end}
    sort(events.begin(), events.end());
    vector<vector<int>> res;
    int hall = -1, start = 0, end = 0;
    for (auto& ev : events) {
        if (res.empty() || ev[0] != hall || ev[1] > end) {
            if (!res.empty()) res.push_back({hall, start, end});
            hall = ev[0]; start = ev[1]; end = ev[2];
        } else {
            end = max(end, ev[2]);
        }
    }
    if (!events.empty()) res.push_back({hall, start, end});
    return res;
}

