import java.util.*;

class Solution {
    public List<int[]> mergeEvents(int[][] events) { // {hall, start, end}
        Arrays.sort(events, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
        List<int[]> res = new ArrayList<>();
        int hall = -1, start = 0, end = 0;
        for (int[] ev : events) {
            if (res.isEmpty() || ev[0] != hall || ev[1] > end) {
                if (!res.isEmpty()) res.add(new int[]{hall, start, end});
                hall = ev[0]; start = ev[1]; end = ev[2];
            } else {
                end = Math.max(end, ev[2]);
            }
        }
        if (!events.isEmpty()) res.add(new int[]{hall, start, end});
        return res;
    }
}

